using System;
using System.Collections.Generic;
using System.Net;
using System.Text;

namespace UI_Desktop.Store;

internal static class StoreCartHtmlBuilder
{
	public static string BuildDocument(DesktopCartResponse cart, StoreWebHomeContext context, DesktopAccountResponse? account)
	{
		return $"<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\r\n<title>Giỏ hàng của bạn - NestG</title>\r\n<style>{Styles()}{StoreWarpHeaderHtml.Styles}{StoreWindowsUpdateHeaderHtml.Styles}{StoreSteamConnectionHeaderHtml.Styles}{StoreSupportContactHeaderHtml.Styles}</style>\r\n</head>\r\n<body>\r\n<header class=\"chrome\" data-drag-region>\r\n    <div class=\"nestg-brand-warp\">\r\n        <button class=\"brand\" data-host-action=\"backHome\">\r\n            <span class=\"brand-logo\"><img src=\"https://nestg-assets.local/logo.png\" alt=\"\" /></span>\r\n            <strong>NestG</strong>\r\n        </button>\r\n        {StoreWarpHeaderHtml.Render()}\r\n        {StoreWindowsUpdateHeaderHtml.Render()}\r\n        {StoreSteamConnectionHeaderHtml.Render()}\r\n    </div>\r\n    <nav>\r\n        <button data-host-action=\"backHome\">Cửa hàng</button>\r\n        <button class=\"active\">Giỏ hàng</button>\r\n        <button data-host-action=\"openLibrary\">Thư viện</button>\r\n    </nav>\r\n    <div class=\"nestg-header-account\">\r\n        {StoreSupportContactHeaderHtml.Render()}\r\n        {Account(account, context)}\r\n    </div>\r\n    <div class=\"window-buttons\">\r\n        <button type=\"button\" data-host-action=\"minimize\" aria-label=\"Thu nhỏ cửa sổ\">-</button>\r\n        <button type=\"button\" data-host-action=\"toggleMaximize\" aria-label=\"Phóng to hoặc khôi phục cửa sổ\">&#9633;</button>\r\n        <button type=\"button\" class=\"close\" data-host-action=\"close\" aria-label=\"Đóng cửa sổ\">&#215;</button>\r\n    </div>\r\n</header>\r\n<main>\r\n    <div class=\"crumb\"><button data-host-action=\"backHome\">Trang chủ</button><span>&gt;</span><b>Giỏ hàng của bạn</b></div>\r\n    <h1>Giỏ hàng của bạn</h1>\r\n    {(cart.IsEmpty ? Empty() : Cart(cart))}\r\n</main>\r\n{CheckoutModal(cart)}\r\n{DeleteConfirmationModal()}\r\n<div class=\"loading\" data-app-loading hidden><div><small>ĐANG XỬ LÝ</small><h2 data-loading-title></h2><p data-loading-message></p></div></div>\r\n<div class=\"toasts\" data-toast-host aria-live=\"polite\" aria-atomic=\"true\"></div>\r\n<script>{Script()}</script>\r\n</body>\r\n</html>";
	}

	private static string Account(DesktopAccountResponse? account, StoreWebHomeContext context)
	{
		if (account == null)
		{
			return $"<button class=\"simple-account\" data-host-action=\"openProfile\"><b>{Initial(context.UserName)}</b><span>{Html(context.UserName)}</span></button>";
		}
		return StoreAccountMenuHtml.Build(account, string.Empty, context.NotificationUnreadCount);
	}

	private static string Cart(DesktopCartResponse cart)
	{
		return $"<div class=\"layout\">\r\n    <section class=\"cart-panel\">\r\n        <div class=\"items\">{ComboItems(cart.ComboItems)}{Items(cart.Items)}</div>\r\n        <footer>\r\n            <button class=\"continue\" data-host-action=\"backHome\">Tiếp tục mua sắm</button>\r\n            <button class=\"clear\" data-host-action=\"clearCart\">Xóa tất cả</button>\r\n        </footer>\r\n    </section>\r\n    <aside>\r\n        <section class=\"summary\">\r\n            <span>TỔNG TẠM TÍNH</span>\r\n            <strong>{Html(cart.TotalAmountText)}</strong>\r\n            {((cart.DiscountAmount > 0m) ? ("<div class=\"discount\"><span>Đã giảm</span><b>-" + Html(cart.DiscountAmountText) + "</b></div>") : string.Empty)}\r\n            {Promo(cart)}\r\n            {PaymentMethods(cart)}\r\n            <p>Thuế (nếu có) sẽ được tính ở bước thanh toán.</p>\r\n            <button class=\"buy\"\r\n                    data-host-action=\"checkoutCart\"\r\n                    data-checkout-button\r\n                    data-sepay-label=\"Mua ngay với SePay\"\r\n                    data-wallet-label=\"Thanh toán bằng ví NestG\">Mua ngay với SePay</button>\r\n        </section>\r\n        <section class=\"license\">\r\n            <div class=\"art\"><i></i><i></i><i></i></div>\r\n            <p>Việc mua sản phẩm số sẽ cấp giấy phép sử dụng sản phẩm trên NestG. Xem đầy đủ điều khoản trong Thỏa thuận người dùng NestG.</p>\r\n        </section>\r\n    </aside>\r\n</div>";
	}

	private static string PaymentMethods(DesktopCartResponse cart)
	{
		string value = (cart.CanPayWithWallet ? string.Empty : " is-disabled");
		string value2 = (cart.CanPayWithWallet ? string.Empty : " disabled");
		string value3 = ((!string.Equals(cart.WalletStatus, "active", StringComparison.OrdinalIgnoreCase)) ? ("Ví hiện đang ở trạng thái " + cart.WalletStatus + ". Hãy kiểm tra lại ví trước khi thanh toán.") : ((!cart.CanPayWithWallet) ? $"Số dư {cart.WalletBalanceText}. Cần nạp thêm {cart.WalletShortfallText} để dùng ví." : ("Số dư " + cart.WalletBalanceText + " đủ để thanh toán ngay.")));
		return $"<section class=\"payment-methods\" aria-labelledby=\"cartPaymentTitle\">\r\n    <h2 id=\"cartPaymentTitle\">Phương thức thanh toán</h2>\r\n    <label class=\"payment-method-option is-active\" data-payment-option>\r\n        <input type=\"radio\" name=\"paymentMethod\" value=\"sepay\" checked data-payment-choice />\r\n        <span class=\"payment-method-radio\" aria-hidden=\"true\"></span>\r\n        <span class=\"payment-method-copy\">\r\n            <strong>SePay QR</strong>\r\n            <small>Quét QR hoặc chuyển khoản ngân hàng.</small>\r\n        </span>\r\n    </label>\r\n    <label class=\"payment-method-option{value}\" data-payment-option>\r\n        <input type=\"radio\" name=\"paymentMethod\" value=\"wallet\" data-payment-choice{value2} />\r\n        <span class=\"payment-method-radio\" aria-hidden=\"true\"></span>\r\n        <span class=\"payment-method-copy\">\r\n            <strong>Ví NestG</strong>\r\n            <small>{Html(value3)}</small>\r\n        </span>\r\n    </label>\r\n    {(cart.CanPayWithWallet ? string.Empty : "<button type=\"button\" class=\"wallet-topup-link\" data-host-action=\"openWalletTopupModal\">Nạp ví NestG</button>")}\r\n</section>";
	}

	private static string Promo(DesktopCartResponse cart)
	{
		return $"<form class=\"promo-form\" data-cart-promo-form>\r\n    <label class=\"promo-label\" for=\"cartPromoCode\">Mã giảm giá</label>\r\n    <div class=\"promo-shell\">\r\n        <input id=\"cartPromoCode\" data-cart-promo-input type=\"text\" value=\"{Attr(cart.PromoCode)}\" placeholder=\"Ví dụ: NestG10\" autocomplete=\"off\" />\r\n        <button type=\"submit\">Áp dụng</button>\r\n    </div>\r\n    {PromoSuggestions(cart.PromoSuggestions)}\r\n    {PromoMessage(cart)}\r\n</form>";
	}

	private static string PromoSuggestions(IReadOnlyList<DesktopCartPromoSuggestionResponse> suggestions)
	{
		if (suggestions.Count == 0)
		{
			return "<div class=\"promo-empty\">Chưa có voucher phù hợp cho giỏ hàng hiện tại.</div>";
		}
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append("<div class=\"promo-suggestions\">");
		foreach (DesktopCartPromoSuggestionResponse suggestion in suggestions)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(149, 6, stringBuilder2);
			handler.AppendLiteral("<button class=\"promo-chip ");
			handler.AppendFormatted(suggestion.IsApplied ? "is-active" : string.Empty);
			handler.AppendLiteral("\" type=\"button\" data-cart-promo-fill=\"");
			handler.AppendFormatted(Attr(suggestion.Code));
			handler.AppendLiteral("\" title=\"");
			handler.AppendFormatted(Attr(suggestion.Description));
			handler.AppendLiteral("\">\r\n    <strong>");
			handler.AppendFormatted(Html(suggestion.Code));
			handler.AppendLiteral("</strong>\r\n    <span>");
			handler.AppendFormatted(Html(suggestion.Title));
			handler.AppendLiteral("</span>\r\n    <small>");
			handler.AppendFormatted(Html(suggestion.Description));
			handler.AppendLiteral("</small>\r\n</button>");
			stringBuilder2.Append(ref handler);
		}
		stringBuilder.Append("</div>");
		return stringBuilder.ToString();
	}

	private static string PromoMessage(DesktopCartResponse cart)
	{
		if (string.IsNullOrWhiteSpace(cart.PromoMessage))
		{
			return string.Empty;
		}
		string value = (cart.PromoInvalid ? "promo-message is-error" : "promo-message is-success");
		string value2 = (string.IsNullOrWhiteSpace(cart.PromoDescription) ? string.Empty : ("<span>" + Html(cart.PromoDescription) + "</span>"));
		return $"<div class=\"{value}\">\r\n    <strong>{Html(cart.PromoMessage)}</strong>\r\n    {value2}\r\n</div>";
	}

	private static string Items(IReadOnlyList<DesktopCartLineItemResponse> items)
	{
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopCartLineItemResponse item in items)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(540, 8, stringBuilder2);
			handler.AppendLiteral("<article class=\"item\">\r\n    <button class=\"cover\" data-host-action=\"openGame\" data-game-id=\"");
			handler.AppendFormatted(item.GameId, "D");
			handler.AppendLiteral("\"><img src=\"");
			handler.AppendFormatted(Attr(item.PosterImageUrl));
			handler.AppendLiteral("\" alt=\"");
			handler.AppendFormatted(Attr(item.Name));
			handler.AppendLiteral("\" /></button>\r\n    <div class=\"info\">\r\n        <div class=\"item-head\">\r\n            <button class=\"name\" data-host-action=\"openGame\" data-game-id=\"");
			handler.AppendFormatted(item.GameId, "D");
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(item.Name));
			handler.AppendLiteral("</button>\r\n            <button class=\"remove\" data-host-action=\"removeCartItem\" data-cart-item-id=\"");
			handler.AppendFormatted(item.CartItemId, "D");
			handler.AppendLiteral("\">Xóa</button>\r\n        </div>\r\n        <span class=\"version\">");
			handler.AppendFormatted(Html(item.VersionName));
			handler.AppendLiteral("</span>\r\n        <span class=\"platform\">&#9638;</span>\r\n        <strong class=\"price\">");
			handler.AppendFormatted(Html(item.LineTotalText));
			handler.AppendLiteral("</strong>\r\n    </div>\r\n</article>");
			stringBuilder2.Append(ref handler);
		}
		return stringBuilder.ToString();
	}

	private static string ComboItems(IReadOnlyList<DesktopComboCartLineItemResponse> items)
	{
		StringBuilder stringBuilder = new StringBuilder();
		foreach (DesktopComboCartLineItemResponse item in items)
		{
			StringBuilder stringBuilder2 = stringBuilder;
			StringBuilder.AppendInterpolatedStringHandler handler = new StringBuilder.AppendInterpolatedStringHandler(596, 8, stringBuilder2);
			handler.AppendLiteral("<article class=\"item combo-item\">\r\n    <button class=\"cover\" data-host-action=\"openCombo\" data-combo-id=\"");
			handler.AppendFormatted(item.ComboId, "D");
			handler.AppendLiteral("\"><img src=\"");
			handler.AppendFormatted(Attr(item.PosterImageUrl));
			handler.AppendLiteral("\" alt=\"");
			handler.AppendFormatted(Attr(item.Name));
			handler.AppendLiteral("\" /></button>\r\n    <div class=\"info\">\r\n        <div class=\"item-head\">\r\n            <button class=\"name\" data-host-action=\"openCombo\" data-combo-id=\"");
			handler.AppendFormatted(item.ComboId, "D");
			handler.AppendLiteral("\">");
			handler.AppendFormatted(Html(item.Name));
			handler.AppendLiteral("</button>\r\n            <button class=\"remove\" data-host-action=\"removeComboCartItem\" data-combo-cart-item-id=\"");
			handler.AppendFormatted(item.ComboCartItemId, "D");
			handler.AppendLiteral("\">Xóa</button>\r\n        </div>\r\n        <span class=\"version\">COMBO GAME · ");
			handler.AppendFormatted(item.ComponentCount);
			handler.AppendLiteral(" game</span>\r\n        <span class=\"platform\">Số lượng cố định: 1</span>\r\n        <strong class=\"price\">");
			handler.AppendFormatted(Html(item.LineTotalText));
			handler.AppendLiteral("</strong>\r\n    </div>\r\n</article>");
			stringBuilder2.Append(ref handler);
		}
		return stringBuilder.ToString();
	}

	private static string Empty()
	{
		return "<section class=\"empty\"><b>N</b><h2>Giỏ hàng đang trống</h2><p>Khám phá cửa hàng và thêm game bạn muốn sở hữu.</p><button data-host-action=\"backHome\">Tiếp tục mua sắm</button></section>";
	}

	private static string CheckoutModal(DesktopCartResponse cart)
	{
		return "<div class=\"checkout-modal\" data-order-checkout-modal hidden>\r\n <div class=\"checkout-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"checkoutDialogTitle\" tabindex=\"-1\">\r\n  <button type=\"button\" class=\"checkout-close\" data-order-checkout-close aria-label=\"Đóng thanh toán\">&#215;</button>\r\n  <div class=\"checkout-grid\">\r\n   <section class=\"qr-card\"><small>THANH TOÁN NESTG</small><h2 id=\"checkoutDialogTitle\" data-order-checkout-title></h2><p data-order-checkout-status aria-live=\"polite\"></p>\r\n    <div class=\"qr\">\r\n     <img data-order-checkout-qr alt=\"QR thanh toán\" />\r\n     <b data-order-checkout-qr-empty hidden>Không có mã QR.</b>\r\n     <div class=\"wallet-success-card\" data-order-checkout-wallet-success hidden>\r\n      <span class=\"wallet-success-icon\" aria-hidden=\"true\"></span>\r\n      <strong>Thanh toán ví thành công</strong>\r\n      <small>Đơn hàng đã hoàn tất và sản phẩm đã sẵn sàng trong thư viện.</small>\r\n     </div>\r\n    </div>\r\n    <span>Tổng cần thanh toán</span><strong data-order-checkout-total></strong>\r\n   </section>\r\n   <div class=\"checkout-info\">\r\n    <section data-transfer-section><h3>Thông tin chuyển khoản</h3><dl>\r\n     <dt>Ngân hàng</dt><dd data-order-checkout-bank></dd><dt>Số tài khoản</dt><dd class=\"transfer-copy\"><span data-order-checkout-account></span><button type=\"button\" data-copy-selector=\"[data-order-checkout-account]\" aria-label=\"Sao chép số tài khoản\">Sao chép</button></dd>\r\n     <dt>Chủ tài khoản</dt><dd data-order-checkout-owner></dd><dt>Nội dung CK</dt><dd class=\"transfer-copy\"><span data-order-checkout-content></span><button type=\"button\" data-copy-selector=\"[data-order-checkout-content]\" aria-label=\"Sao chép nội dung chuyển khoản\">Sao chép</button></dd>\r\n     <dt>Hết hạn</dt><dd data-order-checkout-expires></dd>\r\n    </dl></section>\r\n    <section><h3>Sản phẩm trong đơn</h3><div data-order-checkout-items></div></section>\r\n    <div class=\"checkout-actions\"><button data-order-checkout-refresh>Làm mới trạng thái</button><button class=\"done\" data-order-checkout-confirm hidden>Hoàn tất</button></div>\r\n   </div>\r\n  </div>\r\n </div>\r\n</div>\r\n<div class=\"wallet-confirm-modal\" data-wallet-checkout-confirm hidden>\r\n <div class=\"wallet-confirm-backdrop\" data-wallet-confirm-cancel></div>\r\n <section class=\"wallet-confirm-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"walletConfirmTitle\">\r\n  <span class=\"wallet-confirm-icon\" aria-hidden=\"true\"></span>\r\n  <span class=\"wallet-confirm-kicker\">VÍ NESTG</span>\r\n  <h2 id=\"walletConfirmTitle\">Xác nhận thanh toán bằng ví</h2>\r\n  <p>Hệ thống sẽ trừ số dư ví và hoàn tất đơn hàng ngay sau khi xác nhận.</p>\r\n  <dl>\r\n   <dt>Giỏ hàng</dt><dd>Đơn hàng hiện tại</dd>\r\n   <dt>Số tiền</dt><dd data-wallet-confirm-total>" + Html(cart.TotalAmountText) + "</dd>\r\n  </dl>\r\n  <div class=\"wallet-confirm-actions\">\r\n   <button type=\"button\" data-wallet-confirm-cancel>Hủy</button>\r\n   <button type=\"button\" data-wallet-confirm-submit>Xác nhận thanh toán</button>\r\n  </div>\r\n </section>\r\n</div>";
	}

	private static string DeleteConfirmationModal()
	{
		return "<div class=\"delete-modal\" data-delete-modal hidden>\r\n    <section class=\"delete-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"deleteDialogTitle\">\r\n        <div class=\"delete-icon\">!</div>\r\n        <span class=\"delete-kicker\">XÁC NHẬN GIỎ HÀNG</span>\r\n        <h2 id=\"deleteDialogTitle\" data-delete-title>Xóa sản phẩm?</h2>\r\n        <p data-delete-message>Sản phẩm sẽ được xóa khỏi giỏ hàng của bạn.</p>\r\n        <div class=\"delete-actions\">\r\n            <button type=\"button\" class=\"delete-cancel\" data-delete-cancel>Giữ lại</button>\r\n            <button type=\"button\" class=\"delete-confirm\" data-delete-confirm>Xác nhận xóa</button>\r\n        </div>\r\n    </section>\r\n</div>";
	}

	private static string Styles()
	{
		return ":root {\r\n    color-scheme: dark;\r\n    --bg: #070d14;\r\n    --bar: #080c12;\r\n    --line: #203044;\r\n    --line-soft: rgba(83,117,155,.34);\r\n    --text: #f2f7ff;\r\n    --muted: #8fa0b6;\r\n    --soft: #c5d1df;\r\n    --cyan: #27d9ff;\r\n    --blue: #289bed;\r\n    --gold: #ffd26a;\r\n    --panel: #101a26;\r\n    --panel-2: #0c151f;\r\n    --shadow: 0 18px 44px rgba(0,0,0,.38);\r\n}\r\n* { box-sizing: border-box; }\r\nhtml, body { min-height: 100%; margin: 0; }\r\n[hidden] { display: none !important; }\r\nbody {\r\n    min-width: 0;\r\n    overflow-x: hidden;\r\n    background:\r\n        radial-gradient(circle at 50% -20%, rgba(39,120,170,.18), transparent 34%),\r\n        linear-gradient(180deg, #0b121b 0, #060b11 100%);\r\n    color: var(--text);\r\n    font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\r\n}\r\nbutton { border: 0; font: inherit; color: inherit; cursor: pointer; }\r\nimg { display: block; width: 100%; height: 100%; object-fit: cover; user-select: none; -webkit-user-drag: none; }\r\nbody::-webkit-scrollbar { width: 10px; }\r\nbody::-webkit-scrollbar-track { background: rgba(8,13,20,.65); }\r\nbody::-webkit-scrollbar-thumb { border: 2px solid rgba(8,13,20,.65); border-radius: 999px; background: rgba(61,106,145,.86); }\r\n\r\n.chrome {\r\n    position: sticky;\r\n    top: 0;\r\n    z-index: 60;\r\n    min-height: 68px;\r\n    display: grid;\r\n    grid-template-columns: auto minmax(260px,1fr) auto auto;\r\n    align-items: center;\r\n    gap: clamp(10px,1.2vw,20px);\r\n    padding: 8px clamp(14px,1.3vw,24px);\r\n    border-bottom: 1px solid rgba(75,95,120,.22);\r\n    background: linear-gradient(180deg, rgba(9,13,19,.98), rgba(8,13,20,.95));\r\n    box-shadow: 0 12px 32px rgba(0,0,0,.36);\r\n    backdrop-filter: blur(18px);\r\n}\r\n.brand, .simple-account { display: flex; align-items: center; gap: 10px; padding: 0; background: transparent; white-space: nowrap; }\r\n.brand-logo {\r\n    width: 32px;\r\n    height: 36px;\r\n    display: grid;\r\n    place-items: center;\r\n    overflow: visible;\r\n    flex: 0 0 auto;\r\n}\r\n.brand-logo img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: contain;\r\n    filter: drop-shadow(0 8px 16px rgba(136,18,28,.28));\r\n}\r\n.simple-account b {\r\n    width: 36px;\r\n    height: 36px;\r\n    display: grid;\r\n    place-items: center;\r\n    border: 1px solid #2b5c82;\r\n    border-radius: 5px;\r\n    background: linear-gradient(180deg,#173d59,#0e273b);\r\n    color: #9ed6ff;\r\n    box-shadow: inset 0 0 18px rgba(39,217,255,.05);\r\n}\r\n.brand strong {\r\n    color: #f5f7fb;\r\n    font-size: 18px;\r\n    font-weight: 900;\r\n    letter-spacing: .02em;\r\n}\r\n.chrome nav { justify-self: center; display: flex; align-items: center; gap: clamp(16px,2vw,34px); }\r\n.chrome nav button {\r\n    position: relative;\r\n    min-height: 40px;\r\n    padding: 0;\r\n    background: transparent;\r\n    color: #a6b3c5;\r\n    font-size: clamp(12px,.9vw,15px);\r\n    font-weight: 800;\r\n    letter-spacing: .04em;\r\n}\r\n.chrome nav button:hover { color: #fff; }\r\n.chrome nav button.active { color: #fff; }\r\n.chrome nav button.active::after {\r\n    content: \"\";\r\n    position: absolute;\r\n    right: 0;\r\n    bottom: 0;\r\n    left: 0;\r\n    height: 3px;\r\n    background: var(--cyan);\r\n    box-shadow: 0 0 18px rgba(39,217,255,.55);\r\n}\r\n.simple-account {\r\n    min-width: 0;\r\n    padding: 5px 10px 5px 5px;\r\n    border: 1px solid #2b5c82;\r\n    border-radius: 5px;\r\n    background: #173652;\r\n    color: #dceeff;\r\n}\r\n.simple-account span { max-width: 135px; overflow: hidden; text-overflow: ellipsis; }\r\n" + StoreAccountMenuHtml.Styles + "\r\n.account-menu-shell { justify-self: end; }\r\n.account-chip {\r\n    width: auto;\r\n    min-width: 190px;\r\n    min-height: 42px;\r\n    display: inline-flex;\r\n    align-items: center;\r\n    flex-wrap: nowrap;\r\n    gap: 9px;\r\n    padding: 5px 10px 5px 5px;\r\n  