 0; z-index: 70; display: grid; place-items: center; padding: 20px; background: rgba(3,8,13,.68); backdrop-filter: blur(8px); }\r\n.loading > div { width: min(420px,100%); padding: 24px; border: 1px solid var(--line-soft); border-radius: 7px; background: #0a1b29; box-shadow: var(--shadow); }\r\n.loading small { color: var(--cyan); font-weight: 950; letter-spacing: .08em; }\r\n.loading h2 { margin: 8px 0; }\r\n.loading p { margin: 0; color: var(--muted); }\r\n.toasts { position: fixed; right: 18px; bottom: 18px; z-index: 100; display: grid; gap: 8px; }\r\n.toast { max-width: min(360px,calc(100vw - 36px)); padding: 12px 14px; border: 1px solid var(--line-soft); border-radius: 5px; background: rgba(9,24,36,.97); box-shadow: var(--shadow); }\r\n\r\n@media (max-width: 1180px) {\r\n    .chrome { grid-template-columns: auto minmax(220px,1fr) auto auto; }\r\n    .account-chip { min-width: 170px; }\r\n    .layout { grid-template-columns: minmax(0,1fr) 310px; }\r\n    .item { grid-template-columns: clamp(180px,23vw,235px) minmax(0,1fr); }\r\n}\r\n@media (max-width: 940px) {\r\n    .chrome { grid-template-columns: auto 1fr auto; }\r\n    .chrome nav { justify-self: end; }\r\n    .account-menu-shell, .simple-account { display: none; }\r\n    .window-buttons { grid-column: 3; }\r\n    .layout { grid-template-columns: 1fr; }\r\n    aside { position: static; grid-template-columns: minmax(0,1.1fr) minmax(250px,.9fr); }\r\n    .summary, .license { min-height: 100%; }\r\n    .item { grid-template-columns: clamp(200px,34vw,280px) minmax(0,1fr); }\r\n}\r\n@media (max-width: 680px) {\r\n    .chrome {\r\n        min-height: auto;\r\n        grid-template-columns: auto 1fr auto;\r\n        gap: 8px;\r\n        padding: 8px 10px;\r\n    }\r\n    .brand strong { display: none; }\r\n    .chrome nav { justify-self: center; gap: 14px; }\r\n    .chrome nav button { min-height: 36px; font-size: 11px; }\r\n    .chrome nav button:nth-child(3) { display: none; }\r\n    .window-buttons button { width: 28px; }\r\n    .window-buttons button:nth-child(1) { display: none; }\r\n    main { width: calc(100% - 24px); padding-top: 22px; }\r\n    main > h1 { margin-bottom: 20px; }\r\n    .crumb { font-size: 12px; }\r\n    .item {\r\n        grid-template-columns: minmax(112px,36vw) minmax(0,1fr);\r\n        gap: 13px;\r\n        padding: 15px 0;\r\n    }\r\n    .name { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 3; font-size: 16px; }\r\n    .version { display: -webkit-box; overflow: hidden; -webkit-box-orient: vertical; -webkit-line-clamp: 1; margin-top: 5px; font-size: 11px; }\r\n    .remove { padding: 3px 5px; font-size: 11px; }\r\n    .platform { width: 29px; height: 29px; margin-top: 10px; font-size: 14px; }\r\n    .info { padding-bottom: 32px; }\r\n    .price { bottom: 4px; font-size: 16px; }\r\n    .cart-panel footer { min-height: 64px; padding: 10px 14px; }\r\n    .continue { min-height: 40px; padding: 0 13px; font-size: 12px; }\r\n    .clear { font-size: 12px; }\r\n    aside { grid-template-columns: 1fr; }\r\n    .license { display: none; }\r\n    .summary { padding: 22px; }\r\n    .checkout-modal { padding: 10px; }\r\n    .checkout-dialog { width: 100%; max-height: calc(100vh - 20px); }\r\n    .checkout-grid { grid-template-columns: 1fr; padding: 16px; }\r\n    .checkout-info dl { grid-template-columns: 1fr; gap: 4px; }\r\n    .checkout-info dd { margin-bottom: 8px; }\r\n    .delete-dialog { padding: 23px 18px; }\r\n}\r\n@media (max-width: 430px) {\r\n    .chrome nav { gap: 10px; }\r\n    .chrome nav button { font-size: 10px; }\r\n    .window-buttons button:nth-child(2) { display: none; }\r\n    .item { grid-template-columns: 104px minmax(0,1fr); }\r\n    .item-head { gap: 4px; }\r\n    .name { font-size: 14px; -webkit-line-clamp: 2; }\r\n    .remove { padding-inline: 3px; }\r\n    .platform { display: none; }\r\n    .info { padding-bottom: 28px; }\r\n    .price { font-size: 14px; }\r\n}";
