	{
		return "(()=>{const post=m=>window.chrome?.webview?.postMessage(m);" + StoreAccountMenuHtml.Script + "\r\nconst loading=document.querySelector('[data-app-loading]'),toasts=document.querySelector('[data-toast-host]'),modal=document.querySelector('[data-order-checkout-modal]'),qr=document.querySelector('[data-order-checkout-qr]'),qrEmpty=document.querySelector('[data-order-checkout-qr-empty]'),walletSuccess=document.querySelector('[data-order-checkout-wallet-success]'),items=document.querySelector('[data-order-checkout-items]'),refresh=document.querySelector('[data-order-checkout-refresh]'),checkoutConfirm=document.querySelector('[data-order-checkout-confirm]'),transferSection=document.querySelector('[data-transfer-section]'),walletConfirm=document.querySelector('[data-wallet-checkout-confirm]'),walletConfirmTotal=document.querySelector('[data-wallet-confirm-total]'),walletConfirmSubmit=document.querySelector('[data-wallet-confirm-submit]'),deleteModal=document.querySelector('[data-delete-modal]'),deleteTitle=document.querySelector('[data-delete-title]'),deleteMessage=document.querySelector('[data-delete-message]'),promoInput=document.querySelector('[data-cart-promo-input]'),paymentChoices=document.querySelectorAll('[data-payment-choice]'),paymentOptions=document.querySelectorAll('[data-payment-option]'),checkoutButton=document.querySelector('[data-checkout-button]');let code='',timer=0,pendingDelete=null;\r\nconst text=(s,v)=>{const e=document.querySelector(s);if(e)e.textContent=v||''};const toast=m=>{if(!m||!toasts)return;const e=document.createElement('div');e.className='toast';e.textContent=m;toasts.append(e);setTimeout(()=>e.remove(),3500)};\r\nfunction scrollY(){return Math.max(0,Math.round(window.scrollY||document.documentElement.scrollTop||0))}\r\nfunction applyPromo(value){post({type:'applyCartPromo',promoCode:(value??promoInput?.value??'').trim(),scrollY:scrollY()})}\r\nfunction selectedPaymentMethod(){let value='sepay';paymentChoices.forEach(choice=>{if(c