(p.statusDescription||'Thanh toán thành công.')}}\r\nfunction show(p){if(!modal||!p)return;const isWallet=!!p.isWalletPayment||p.hasQrCode===false;const qrImageUrl=isWallet?'':(p.qrImageUrl||'');code=p.orderCode||'';modal.classList.toggle('is-wallet-payment',isWallet);text('[data-order-checkout-title]',p.pageTitle||(isWallet?'Hoàn tất thanh toán bằng ví':'Thanh toán đơn hàng'));text('[data-order-checkout-total]',p.totalAmountText);text('[data-order-checkout-bank]',p.bankName);text('[data-order-checkout-account]',p.accountNumber);text('[data-order-checkout-owner]',p.accountName);text('[data-order-checkout-content]',p.transferContent);text('[data-order-checkout-expires]',p.expiresAtText);renderItems(p.items);if(transferSection)transferSection.hidden=isWallet;if(qr){qr.hidden=!qrImageUrl;if(qrImageUrl)qr.src=qrImageUrl;else qr.removeAttribute('src')}if(qrEmpty){qrEmpty.textContent='Không có mã QR.';qrEmpty.hidden=isWallet||!!qrImageUrl}if(walletSuccess)walletSuccess.hidden=!isWallet;if(checkoutConfirm){checkoutConfirm.textContent=isWallet?'Đã hiểu':'Hoàn tất';checkoutConfirm.hidden=!p.isPaid}if(refresh){refresh.hidden=isWallet&&!!p.isPaid;if(!isWallet){refresh.hidden=false;refresh.disabled=false;refresh.textContent='Làm mới trạng thái'}}modal.hidden=false;document.body.style.overflow='hidden';status(p);if(isWallet&&refresh)refresh.hidden=true;clearInterval(timer);if(!p.isPaid&&code&&!isWallet)timer=setInterval(()=>post({type:'refreshOrderCheckoutStatus',orderCode:code}),5000)}\r\nfunction closeCheckout(ok){clearInterval(timer);if(modal)modal.hidden=true;closeWalletConfirm();document.body.style.overflow='';post({type:ok?'confirmOrderCheckoutSuccess':'closeOrderCheckoutPopup',orderCode:code});code=''}\r\nfunction openDelete(type,cartItemId,name){pendingDelete={type,cartItemId,scrollY:Math.max(0,Math.round(window.scrollY||document.documentElement.scrollTop||0))};if(deleteTitle)deleteTitle.textContent=type==='clearCart'?'Xóa toàn bộ giỏ hàng?':'Xóa sản phẩm?';if(deleteMessage)deleteMessage.textContent=type==='clearCart'?'Tất cả sản phẩm trong giỏ hàng sẽ bị xóa.':name?`\"${name}\" sẽ được xóa khỏi giỏ hàng.`:'Sản phẩm sẽ được xóa khỏi giỏ hàng.';if(deleteModal)deleteModal.hidden=false;document.body.style.overflow='hidden'}\r\nfunction closeDelete(){if(deleteModal)deleteModal.hidden=true;document.body.style.overflow='';pendingDelete=null}\r\nwindow.__nestgHome={toast,setCartCount(){},setWalletBalance(){}};window.__nestgLoading={show(t,m){text('[data-loading-title]',t);text('[data-loading-message]',m);if(loading)loading.hidden=false},hide(){if(loading)loading.hidden=true}};window.__nestgOrderCheckout={show,updateStatus:status};\r\nconst modalElements=[modal,walletConfirm,deleteModal].filter(Boolean);let lastModalFocus=null;\r\nfunction activeModal(){return modalElements.find(element=>!element.hidden)||null}\r\nfunction modalFocusables(element){return Array.from(element.querySelectorAll('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex]:not([tabindex=\"-1\"])')).filter(item=>!item.hidden)}\r\nmodalElements.forEach(element=>{new MutationObserver(()=>{if(!element.hidden){lastModalFocus=document.activeElement instanceof HTMLElement?document.activeElement:null;window.setTimeout(()=>{const focusable=modalFocusables(element);(focusable[0]||element.querySelector('[role=\"dialog\"]'))?.focus?.()},0)}else{lastModalFocus?.focus?.()}}).observe(element,{attributes:true,attributeFilter:['hidden']})});\r\ndocument.addEventListener('submit',e=>{const form=e.target instanceof Element?e.target.closest('[data-cart-promo-form]'):null;if(!form)return;e.preventDefault();applyPromo()});\r\ndocument.addEventListener('click',e=>{const t=e.target instanceof Element?e.target.closest('[data-copy-selector]'):null;if(!t)return;e.preventDefault();e.stopImmediatePropagation();const selector=t.getAttribute('data-copy-selector');const value=selector?document.querySelector(selector)?.textContent?.trim():'';if(!value)return;post({type:'copyText',text:value});toast('Đã sao chép')});\r\ndocument.addEventListener('click',e=>{const t=e.target instanceof Element?e.target:null;if(!t)return;if(t.closest('[data-account-toggle]')){setAccountMenuOpen(!!accountMenu?.hidden);return}if(accountMenu&&!accountMenu.hidden&&!t.closest('.account-menu-shell'))setAccountMenuOpen(false);const promoChip=t.closest('[data-cart-promo-fill]');if(promoChip){const value=promoChip.dataset.cartPromoFill||'';if(promoInput)promoInput.value=value;applyPromo(value);return}if(t.closest('[data-wallet-confirm-cancel]')){closeWalletConfirm();return}if(t.closest('[data-wallet-confirm-submit]')){setWalletConfirmBusy(true);closeWalletConfirm();post({type:'checkoutCart',paymentMethod:'wallet'});return}if(t.closest('[data-delete-cancel]')){closeDelete();return}if(t.closest('[data-delete-confirm]')){if(pendingDelete)post({type:pendingDelete.type,cartItemId:pendingDelete.cartItemId,comboCartItemId:pendingDelete.cartItemId,scrollY:pendingDelete.scrollY});return}if(t.closest('[data-order-checkout-close]')){closeCheckout(false);return}if(t.closest('[data-order-checkout-refresh]')){if(code)post({type:'refreshOrderCheckoutStatus',orderCode:code});return}if(t.closest('[data-order-checkout-confirm]')){closeCheckout(true);return}const a=t.closest('[data-host-action]');if(!a)return;const type=a.dataset.hostAction;if(type==='removeCartItem'){const item=a.closest('.item');openDelete(type,a.dataset.cartItemId,item?.querySelector('.name')?.textContent?.trim()||'');return}if(type==='removeComboCartItem'){const item=a.closest('.item');openDelete(type,a.dataset.comboCartItemId,item?.querySelector('.name')?.textContent?.trim()||'');return}if(type==='clearCart'){openDelete(type,'','');return}if(type==='checkoutCart'){if(selectedPaymentMethod()==='wallet'){openWalletConfirm();return}post({type,paymentMethod:selectedPaymentMethod()});return}post({type,gameId:a.dataset.gameId,comboId:a.dataset.comboId,cartItemId:a.dataset.cartItemId,comboCartItemId:a.dataset.comboCartItemId})});\r\npaymentChoices.forEach(choice=>choice.addEventListener('change',syncPaymentMethod));syncPaymentMethod();\r\ndocument.addEventListener('keydown',e=>{const opened=activeModal();if(e.key==='Tab'&&opened){const focusable=modalFocusables(opened);if(focusable.length){const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}return}if(e.key!=='Escape')return;if(walletConfirm&&!walletConfirm.hidden){closeWalletConfirm();return}if(deleteModal&&!deleteModal.hidden){closeDelete();return}if(modal&&!modal.hidden)closeCheckout(false)});\r\ndocument.addEventListener('dblclick',e=>{if(e.target instanceof Element&&e.target.closest('[data-drag-region]'))post({type:'toggleMaximize'})})})();";
